import{_ as d,o as a,c as e,ah as r}from"./chunks/framework.DuX8SFU5.js";const b=JSON.parse('{"title":"AM_CAN_LOGGER — даташит","description":"","frontmatter":{"title":"AM_CAN_LOGGER — даташит","pdf":"/pdf/AM_CAN_LOGGER_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_can_logger/datasheet.md","filePath":"am_can_logger/datasheet.md"}'),o={name:"am_can_logger/datasheet.md"};function h(l,t,i,c,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h2 id="_1-описание" tabindex="-1">1. Описание <a class="header-anchor" href="#_1-описание" aria-label="Permalink to &quot;1. Описание&quot;">​</a></h2><p>AM_CAN_LOGGER — автономный регистратор CAN-трафика и вибраций на базе полётного контроллера Pixhawk 6X (FMUv6X) с прошивкой на основе PX4. Он слушает две шины CAN, не передавая в них ничего, и записывает каждый кадр с меткой времени на карту microSD в формате <code>candump</code>. Параллельно в журнал ULog пишутся данные акселерометра и гироскопа с полной частотой датчика.</p><h2 id="_2-возможности" tabindex="-1">2. Возможности <a class="header-anchor" href="#_2-возможности" aria-label="Permalink to &quot;2. Возможности&quot;">​</a></h2><ul><li>Две шины CAN, скорость каждой задаётся отдельно, от 10 кбит/с до 1 Мбит/с.</li><li>Режим только приёма: контроллер CAN не подтверждает кадры и не выдаёт ошибок.</li><li>Метка времени ставится в прерывании приёма кадра, с разрешением 1 мкс.</li><li>Запись в стандартном формате <code>candump -L</code>, новый файл каждые 60 секунд.</li><li>Сырые данные акселерометра и гироскопа в ULog для анализа вибраций.</li><li>Автозапуск при подаче питания, запись с момента загрузки.</li><li>Счётчики кадров и потерь по каждой шине.</li><li>Индикация состояния светодиодом.</li><li>Просмотр, выгрузка файлов и перезагрузка по MAVLink через USB или беспроводной модуль.</li></ul><h2 id="_3-характеристики" tabindex="-1">3. Характеристики <a class="header-anchor" href="#_3-характеристики" aria-label="Permalink to &quot;3. Характеристики&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Мин.</th><th>Тип.</th><th>Макс.</th><th>Ед.</th><th>Примечание</th></tr></thead><tbody><tr><td>Число шин CAN</td><td>—</td><td>2</td><td>2</td><td></td><td>CAN1 и CAN2 контроллера</td></tr><tr><td>Скорость шины</td><td>10</td><td>—</td><td>1000</td><td>кбит/с</td><td>Для каждой шины своя</td></tr><tr><td>Формат кадров</td><td></td><td></td><td></td><td></td><td>Классический CAN, 11 и 29 бит; CAN FD не поддерживается</td></tr><tr><td>Разрешение метки времени</td><td>—</td><td>1</td><td>—</td><td>мкс</td><td></td></tr><tr><td>Пропускная способность записи без потерь, пачка</td><td>—</td><td>—</td><td>10,5</td><td>тыс. кадр/с</td><td>2 с, измерено на стенде</td></tr><tr><td>Потери при длительном насыщении шины 1 Мбит/с</td><td>—</td><td>1,2</td><td>—</td><td>%</td><td>20 с, измерено на стенде</td></tr><tr><td>Длительность файла</td><td>0</td><td>60</td><td>3600</td><td>с</td><td>0 — без деления на файлы</td></tr><tr><td>Буфер между приёмом и картой</td><td>4</td><td>128</td><td>512</td><td>КиБ</td><td></td></tr><tr><td>Синхронизация файла на карту</td><td>—</td><td>1</td><td>—</td><td>с</td><td></td></tr><tr><td>Частота записи IMU</td><td>—</td><td>400</td><td>—</td><td>сообщ./с</td><td>Пакеты отсчётов с полной частотой датчика</td></tr><tr><td>Объём записи при 3 тыс. кадр/с</td><td>—</td><td>0,5</td><td>—</td><td>ГБ/ч</td><td>Без сжатия</td></tr></tbody></table><p>Одновременная запись плотного CAN-потока и сырых данных IMU может превысить пропускную способность карты: на стенде при 7 тыс. кадр/с вместе с IMU терялось 27 % кадров. При потоке машины около 3,5 тыс. кадр/с потери на текущей прошивке ещё не измерены.</p><h2 id="_4-подключение" tabindex="-1">4. Подключение <a class="header-anchor" href="#_4-подключение" aria-label="Permalink to &quot;4. Подключение&quot;">​</a></h2><h3 id="_4-1-разъемы-can1-и-can2" tabindex="-1">4.1. Разъёмы CAN1 и CAN2 <a class="header-anchor" href="#_4-1-разъемы-can1-и-can2" aria-label="Permalink to &quot;4.1. Разъёмы CAN1 и CAN2&quot;">​</a></h3><p>JST-GH, 4 контакта, по стандарту разъёмов Pixhawk:</p><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>5 В</td></tr><tr><td>2</td><td>CAN_H</td></tr><tr><td>3</td><td>CAN_L</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><p>Контакт 5 В к шине машины не подключается.</p><h3 id="_4-2-питание" tabindex="-1">4.2. Питание <a class="header-anchor" href="#_4-2-питание" aria-label="Permalink to &quot;4.2. Питание&quot;">​</a></h3><p>Контроллер питается через модуль питания на разъём POWER; от бортовой сети 24 В питание подаётся через преобразователь и предохранитель.</p><h2 id="_5-данные-на-карте" tabindex="-1">5. Данные на карте <a class="header-anchor" href="#_5-данные-на-карте" aria-label="Permalink to &quot;5. Данные на карте&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Путь</th><th>Содержимое</th></tr></thead><tbody><tr><td><code>candump/sessNNN/can_NNNN.log</code></td><td>CAN-кадры; новая сессия при каждом включении, новый файл каждые 60 с</td></tr><tr><td><code>log/sessNNN/logNNN.ulg</code></td><td>ULog: IMU и состояние контроллера</td></tr></tbody></table><p>Строка записи:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1712345678.123456) can0 18EEFF01#0102030405060708</span></span></code></pre></div><p><code>can0</code> — шина CAN1, <code>can1</code> — шина CAN2. Время в скобках — секунды и микросекунды по часам контроллера.</p><h2 id="_6-параметры" tabindex="-1">6. Параметры <a class="header-anchor" href="#_6-параметры" aria-label="Permalink to &quot;6. Параметры&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Назначение</th></tr></thead><tbody><tr><td><code>CANLOG_EN</code></td><td>0</td><td>Запуск регистратора при загрузке</td></tr><tr><td><code>CANLOG_BITRATE1</code></td><td>1000000</td><td>Скорость шины CAN1, бит/с</td></tr><tr><td><code>CANLOG_BITRATE2</code></td><td>1000000</td><td>Скорость шины CAN2, бит/с</td></tr><tr><td><code>CANLOG_IFACES</code></td><td>3</td><td>Маска шин: бит 0 — CAN1, бит 1 — CAN2</td></tr><tr><td><code>CANLOG_SILENT</code></td><td>1</td><td>Только приём</td></tr><tr><td><code>CANLOG_ROT_S</code></td><td>60</td><td>Длительность файла, с; 0 — не делить</td></tr><tr><td><code>CANLOG_BUF_KB</code></td><td>128</td><td>Буфер между приёмом и картой, КиБ</td></tr><tr><td><code>UAVCAN_ENABLE</code></td><td>0</td><td>Должен быть 0: регистратор сам управляет контроллером CAN</td></tr><tr><td><code>SDLOG_MODE</code></td><td>2</td><td>Журнал ULog с момента загрузки</td></tr><tr><td><code>SDLOG_PROFILE</code></td><td>769</td><td>Стандартный набор плюс сырые данные гироскопа и акселерометра</td></tr></tbody></table><h2 id="_7-индикация" tabindex="-1">7. Индикация <a class="header-anchor" href="#_7-индикация" aria-label="Permalink to &quot;7. Индикация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Состояние</th><th>Условие</th><th>Светодиод контроллера</th><th>Внешний RGB-светодиод</th></tr></thead><tbody><tr><td>Запись</td><td>Все включённые шины передали кадры за последние 2 с, потерь нет</td><td>1 Гц</td><td>зелёный, медленно</td></tr><tr><td>Тишина на шине</td><td>Одна из шин молчит дольше 2 с</td><td>короткая вспышка раз в 2 с</td><td>жёлтый, медленно</td></tr><tr><td>Потери</td><td>Потеря кадра или ошибка записи за последние 5 с, либо файл не открыт</td><td>5 Гц</td><td>красный, часто</td></tr></tbody></table><h2 id="_8-диагностика" tabindex="-1">8. Диагностика <a class="header-anchor" href="#_8-диагностика" aria-label="Permalink to &quot;8. Диагностика&quot;">​</a></h2><p>Команда <code>can_logger status</code> в консоли контроллера показывает по каждой шине скорость, число принятых кадров, переполнения очереди драйвера и ошибки шины. Потери разделены на две причины: переполнение буфера означает, что карта не успевает, переполнение очереди драйвера — что задача приёма не успела её вычитать. Доля потерь считается от всех кадров на шине, включая те, что драйвер потерял до регистратора.</p><h2 id="_9-известные-ограничения" tabindex="-1">9. Известные ограничения <a class="header-anchor" href="#_9-известные-ограничения" aria-label="Permalink to &quot;9. Известные ограничения&quot;">​</a></h2><ul><li>Две шины на устройство; для третьей нужен второй регистратор или внешний контроллер CAN.</li><li>Гальванической развязки CAN нет.</li><li>Без внешнего источника времени абсолютное время начинается с 2000-01-01; интервалы между кадрами точные.</li><li>Счётчики потерь не записываются на карту, их видно только в консоли.</li><li>Сжатие записи на устройстве не реализовано.</li><li>Схемы мигания светодиода предварительные.</li></ul><h2 id="_10-история-документа" tabindex="-1">10. История документа <a class="header-anchor" href="#_10-история-документа" aria-label="Permalink to &quot;10. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-10-01</td><td>Первая редакция даташита</td></tr></tbody></table>',29)])])}const N=d(o,[["render",h]]);export{b as __pageData,N as default};
